package cn.creamnote.app;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.media.ExifInterface;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.util.AtomicFile;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;
public class MainActivity extends Activity {
 private WebView web;private File media;private AtomicFile db;private final Object lock=new Object();private final ExecutorService io=Executors.newSingleThreadExecutor();private boolean loaded=false;private final ArrayList<Intent> pending=new ArrayList<>();private static final String ORIGIN="https://app.creamnote.local/";private static final long PHOTO_LIMIT=256L*1024*1024, BACKUP_LIMIT=1024L*1024*1024;
 public void onCreate(Bundle b){super.onCreate(b);media=new File(getFilesDir(),"media");media.mkdirs();db=new AtomicFile(new File(getFilesDir(),"state.json"));recoverRestore();web=new WebView(this);web.setBackgroundColor(Color.rgb(247,247,239));setContentView(web);web.setPadding(0,0,0,0);if(Build.VERSION.SDK_INT>=35){web.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets i=in.getInsets(WindowInsets.Type.systemBars());v.setPadding(i.left,i.top,i.right,i.bottom);return in;});}web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setSupportZoom(false);web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !r.getUrl().toString().startsWith(ORIGIN);}public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){return localResponse(r.getUrl());}});web.loadUrl(ORIGIN+"index.html");handleIntent(getIntent());}
 private WebResourceResponse localResponse(Uri u){try{if(!"app.creamnote.local".equals(u.getHost()))return denied();String p=u.getPath();InputStream stream;String mime;if(p.startsWith("/media/")){String n=p.substring(7);if(!safe(n))return denied();File f=new File(media,n);stream=new FileInputStream(f);mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(MimeTypeMap.getFileExtensionFromUrl(n));if(mime==null)mime="image/jpeg";}else{String n=p.substring(1);if(!Arrays.asList("index.html","style.css","app.js").contains(n))return denied();stream=getAssets().open(n);mime=n.endsWith("html")?"text/html":n.endsWith("css")?"text/css":"application/javascript";}return new WebResourceResponse(mime,"UTF-8",stream);}catch(Exception e){return denied();}}
 private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 static boolean safe(String s){return s!=null&&s.matches("[a-zA-Z0-9][a-zA-Z0-9._-]{0,120}")&&!s.contains("..");}
 private void js(String script){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())web.evaluateJavascript(script,null);});}
 private void message(String text){js("window.nativeMessage("+JSONObject.quote(text)+")");}
 private void busy(boolean b){js("document.body.classList."+(b?"add":"remove")+"('busy')");}
 private String loadState(){synchronized(lock){try{return new String(db.readFully(),StandardCharsets.UTF_8);}catch(FileNotFoundException e){return "{\"version\":1,\"works\":[],\"codes\":[]}";}catch(Exception e){return "";}}}
 private boolean persist(String s){synchronized(lock){FileOutputStream out=null;try{validate(new JSONObject(s),false,null);out=db.startWrite();out.write(s.getBytes(StandardCharsets.UTF_8));db.finishWrite(out);return true;}catch(Exception e){if(out!=null)db.failWrite(out);return false;}}}
 private void validate(JSONObject s,boolean withMedia,File folder)throws Exception{if(s.getInt("version")!=1)throw new IOException();JSONArray works=s.getJSONArray("works"),codes=s.getJSONArray("codes");if(works.length()>10000||codes.length()>50000)throw new IOException();Set<String> ids=new HashSet<>();for(int i=0;i<works.length();i++){JSONObject w=works.getJSONObject(i);checkId(w,ids);for(String k:new String[]{"title","category","note","date","file","thumb"})w.getString(k);w.getBoolean("favorite");w.getLong("created");if(!safe(w.getString("file"))||!safe(w.getString("thumb"))||!w.getString("date").matches("\\d{4}-\\d{2}-\\d{2}"))throw new IOException();if(withMedia)for(String k:new String[]{"file","thumb"})if(!new File(folder,w.getString(k)).isFile())throw new IOException();}for(int i=0;i<codes.length();i++){JSONObject c=codes.getJSONObject(i);checkId(c,ids);for(String k:new String[]{"code","station","note","date"})c.getString(k);c.getBoolean("picked");c.getLong("created");if(c.getString("code").trim().isEmpty()||!c.getString("date").matches("\\d{4}-\\d{2}-\\d{2}"))throw new IOException();}}
 private void checkId(JSONObject w,Set<String> ids)throws Exception{String id=w.getString("id");if(!safe(id)||!ids.add(id))throw new IOException();}
 public class Bridge {
  @JavascriptInterface public String load(){return loadState();}
  @JavascriptInterface public boolean save(String s){if(s==null||s.length()>32*1024*1024)return false;return persist(s);}
  @JavascriptInterface public void ready(){runOnUiThread(()->{loaded=true;for(Intent in:new ArrayList<>(pending))handleIntent(in);pending.clear();});}
  @JavascriptInterface public void pickPhotos(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);try{startActivityForResult(i,1);}catch(Exception e){message("无法打开照片选择器");}});}
  @JavascriptInterface public void copy(String s){runOnUiThread(()->((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("取件码",s)));}
  @JavascriptInterface public String paste(){android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!c.hasPrimaryClip()||c.getPrimaryClip()==null)return "";return c.getPrimaryClip().getItemAt(0).coerceToText(MainActivity.this).toString();}
  @JavascriptInterface public void deletePhoto(String a,String b){io.execute(()->{if(safe(a))new File(media,a).delete();if(safe(b))new File(media,b).delete();});}
  @JavascriptInterface public void sharePhoto(String n){runOnUiThread(()->{if(!safe(n)||!new File(media,n).isFile()){message("原图不存在");return;}Uri u=Uri.parse("content://cn.creamnote.app.photos/"+n);Intent i=new Intent(Intent.ACTION_SEND);i.setType(getContentResolver().getType(u));i.putExtra(Intent.EXTRA_STREAM,u);i.setClipData(ClipData.newRawUri("作品原图",u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(i,"分享作品原图"));}catch(Exception e){message("没有可用的分享应用");}});}
  @JavascriptInterface public void exportBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"奶油小记-备份-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+".zip");try{startActivityForResult(i,2);}catch(Exception e){message("无法打开文件保存器");}});}
  @JavascriptInterface public void importBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/octet-stream"});try{startActivityForResult(i,3);}catch(Exception e){message("无法打开文件选择器");}});}
 }
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;if(r==1){ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());importPhotos(uris);}else if(r==2&&data.getData()!=null)exportBackup(data.getData());else if(r==3&&data.getData()!=null)restore(data.getData());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleIntent(i);}
 private void handleIntent(Intent in){String action=in.getAction();if(!Intent.ACTION_SEND.equals(action)&&!Intent.ACTION_SEND_MULTIPLE.equals(action))return;if(!loaded){pending.add(in);return;}String type=in.getType();if(type!=null&&type.startsWith("image/")){ArrayList<Uri> uris=new ArrayList<>();if(Intent.ACTION_SEND_MULTIPLE.equals(action)){ArrayList<Uri> list=in.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)uris.addAll(list);}else{Uri u=in.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null)uris.add(u);}importPhotos(uris);}else if("text/plain".equals(type)){CharSequence t=in.getCharSequenceExtra(Intent.EXTRA_TEXT);if(t!=null)js("window.receiveText("+JSONObject.quote(t.toString())+")");}}
 private void importPhotos(List<Uri> uris){if(uris.isEmpty())return;busy(true);message("正在保存原图，请稍候…");io.execute(()->{JSONArray list=new JSONArray();int failed=0;for(Uri u:uris){File full=null,thumb=null;try{String mime=getContentResolver().getType(u);String ext=MimeTypeMap.getSingleton().getExtensionFromMimeType(mime);if(ext==null||!ext.matches("[a-zA-Z0-9]+"))ext="jpg";String id=UUID.randomUUID().toString(),name="裱花作品";try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}full=new File(media,id+"."+ext);try(InputStream source=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(full)){copy(source,out,PHOTO_LIMIT);}BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeFile(full.getPath(),opt);if(opt.outWidth<=0||opt.outHeight<=0)throw new IOException();int sample=1;while(Math.max(opt.outWidth,opt.outHeight)/sample>1000)sample*=2;opt.inJustDecodeBounds=false;opt.inSampleSize=sample;Bitmap bm=BitmapFactory.decodeFile(full.getPath(),opt);if(bm==null)throw new IOException();try(InputStream src=new FileInputStream(full)){ExifInterface exif=new ExifInterface(src);int o=exif.getAttributeInt(ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(o){case 2:m.setScale(-1,1);break;case 3:m.setRotate(180);break;case 4:m.setScale(1,-1);break;case 5:m.setRotate(90);m.postScale(-1,1);break;case 6:m.setRotate(90);break;case 7:m.setRotate(270);m.postScale(-1,1);break;case 8:m.setRotate(270);break;}Bitmap adjusted=Bitmap.createBitmap(bm,0,0,bm.getWidth(),bm.getHeight(),m,true);if(adjusted!=bm){bm.recycle();bm=adjusted;}}catch(Exception ignored){}thumb=new File(media,id+"-thumb.jpg");try(OutputStream out=new FileOutputStream(thumb)){if(!bm.compress(Bitmap.CompressFormat.JPEG,88,out))throw new IOException();}finally{bm.recycle();}JSONObject x=new JSONObject();x.put("file",full.getName());x.put("thumb",thumb.getName());x.put("name",name);list.put(x);}catch(Exception|OutOfMemoryError e){failed++;if(full!=null)full.delete();if(thumb!=null)thumb.delete();}}busy(false);if(list.length()>0)js("window.receivePhotos("+list.toString()+")");if(failed>0)message(failed+" 张图片无法读取，请尝试 JPG 或 PNG");});}
 private static long copy(InputStream src,OutputStream out,long cap)throws IOException{if(src==null)throw new IOException();byte[] buf=new byte[65536];long total=0;int n;while((n=src.read(buf))!=-1){total+=n;if(total>cap)throw new IOException("too large");out.write(buf,0,n);}return total;}
 private void exportBackup(Uri uri){busy(true);message("正在导出完整备份…");io.execute(()->{try{String snapshot=loadState();JSONObject s=new JSONObject(snapshot);validate(s,true,media);try(OutputStream target=getContentResolver().openOutputStream(uri,"wt");ZipOutputStream z=new ZipOutputStream(target)){z.putNextEntry(new ZipEntry("state.json"));z.write(snapshot.getBytes(StandardCharsets.UTF_8));z.closeEntry();Set<String> names=new HashSet<>();JSONArray ws=s.getJSONArray("works");for(int i=0;i<ws.length();i++)for(String k:new String[]{"file","thumb"})names.add(ws.getJSONObject(i).getString(k));for(String n:names){z.putNextEntry(new ZipEntry("media/"+n));try(InputStream f=new FileInputStream(new File(media,n))){copy(f,z,PHOTO_LIMIT);}z.closeEntry();}}message("完整备份已导出");}catch(Exception e){message("备份失败，请检查空间并重新导出");}finally{busy(false);}});}
 private void recoverRestore(){File marker=new File(getFilesDir(),"restore-previous.json"),old=new File(getFilesDir(),"previous-media");if(marker.isFile())try{String previous=new String(java.nio.file.Files.readAllBytes(marker.toPath()),StandardCharsets.UTF_8);if(old.isDirectory()){erase(media);if(!old.renameTo(media))return;}if(persist(previous))marker.delete();}catch(Exception ignored){}else if(old.exists())erase(old);}
 private void restore(Uri uri){busy(true);message("正在检查并恢复备份…");io.execute(()->{File stage=new File(getFilesDir(),"restore-"+UUID.randomUUID()),stagedMedia=new File(stage,"media"),old=new File(getFilesDir(),"previous-media");stagedMedia.mkdirs();try{long total=0;int count=0;Set<String> entries=new HashSet<>();try(InputStream raw=getContentResolver().openInputStream(uri);ZipInputStream z=new ZipInputStream(raw)){ZipEntry e;while((e=z.getNextEntry())!=null){if(e.isDirectory())continue;String n=e.getName();if(++count>20001||!entries.add(n))throw new IOException();File dest;if(n.equals("state.json"))dest=new File(stage,n);else if(n.startsWith("media/")&&safe(n.substring(6)))dest=new File(stagedMedia,n.substring(6));else throw new IOException();try(OutputStream out=new FileOutputStream(dest)){total+=copy(z,out,n.equals("state.json")?32L*1024*1024:PHOTO_LIMIT);}if(total>BACKUP_LIMIT)throw new IOException();z.closeEntry();}}File stateFile=new File(stage,"state.json");byte[] bytes=java.nio.file.Files.readAllBytes(stateFile.toPath());String json=new String(bytes,StandardCharsets.UTF_8);JSONObject s=new JSONObject(json);validate(s,true,stagedMedia);synchronized(lock){erase(old);File marker=new File(getFilesDir(),"restore-previous.json");try(FileOutputStream previous=new FileOutputStream(marker)){previous.write(loadState().getBytes(StandardCharsets.UTF_8));previous.getFD().sync();}if(!media.renameTo(old))throw new IOException();if(!stagedMedia.renameTo(media)){old.renameTo(media);throw new IOException();}if(!persist(json)){erase(media);old.renameTo(media);throw new IOException();}if(!marker.delete())throw new IOException();erase(old);}js("window.restoreComplete()");}catch(Exception e){synchronized(lock){recoverRestore();}message("恢复失败：备份无效、不完整或手机空间不足");}finally{erase(stage);busy(false);}});}
 private void erase(File f){if(f.isDirectory()){File[] fs=f.listFiles();if(fs!=null)for(File x:fs)erase(x);}f.delete();}
 @Override public void onBackPressed(){web.evaluateJavascript("window.backFromNative()",r->{if(!"true".equals(r))MainActivity.super.onBackPressed();});}
 @Override protected void onDestroy(){io.shutdown();web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
}
